// Rein lesende Kontrolle aller Beziehungen zwischen den zwoelf
// edoobox-Ressourcen. Es werden nur Mengen und Trefferquoten ausgegeben,
// niemals IDs, Namen, Kontaktdaten oder andere Feldwerte.

const auth = $input.first().json;
const token = typeof auth.data === 'string' ? auth.data : auth.access_token;
const edid = auth.edid ?? auth?.data?.edid;
if (!token || !edid) throw new Error('Token oder edid fehlt.');

const headers = {
  edid,
  'grant-type': 'access_token',
  Authorization: `Bearer ${token}`,
  'Content-Type': 'application/json',
};
const basis = 'https://app1.edoobox.com/v2';

const definitionen = [
  ['admins', '/admin/list'],
  ['vat', '/vat/list'],
  ['countries', '/country/list'],
  ['categories', '/category/list'],
  ['offers', '/offer/list'],
  ['users', '/user/list'],
  ['dates', '/date/list'],
  ['bookings', '/booking/list'],
  ['pricecategories', '/pricecategory/list'],
  ['attendances', '/attendance/list'],
  ['invoices', '/invoice/list'],
  ['transactions', '/transaction/list'],
];

function rowsAus(body) {
  const d = body?.data;
  if (Array.isArray(d)) return d;
  if (d && typeof d === 'object') return Object.values(d);
  return [];
}

async function holeAlle(pfad) {
  const reply = 2000;
  let start = 0;
  let total = null;
  const alle = [];
  for (let seite = 1; seite <= 50; seite += 1) {
    const a = await this.helpers.httpRequest({
      method: 'GET',
      url: basis + pfad,
      headers,
      qs: { 'limit[start]': start, 'limit[reply]': reply },
      json: true,
      returnFullResponse: true,
      timeout: 60000,
      ignoreHttpStatusErrors: true,
    });
    if (!(a.statusCode >= 200 && a.statusCode < 300)) {
      throw new Error(`${pfad}: HTTP ${a.statusCode} bei Offset ${start}`);
    }
    const rows = rowsAus(a.body);
    if (total === null && a.body?.limit?.total !== undefined) total = Number(a.body.limit.total);
    alle.push(...rows);
    start += rows.length;
    if (rows.length === 0 || rows.length < reply || (total !== null && start >= total)) break;
  }
  if (total !== null && alle.length !== total) {
    throw new Error(`${pfad}: unvollstaendig, gemeldet ${total}, gelesen ${alle.length}`);
  }
  return alle;
}

const daten = {};
for (const [name, pfad] of definitionen) {
  daten[name] = await holeAlle.call(this, pfad);
}

function idSet(name) {
  return new Set(daten[name].map((r) => r?.id).filter((v) => v !== null && v !== undefined && v !== false && v !== '').map(String));
}

const ids = Object.fromEntries(definitionen.map(([name]) => [name, idSet(name)]));
const ausgabe = [];

for (const [name, pfad] of definitionen) {
  ausgabe.push({ json: {
    schritt: 'S52',
    bereich: 'A Vollstaendigkeit',
    beziehung: name,
    quellzeilen: daten[name].length,
    zeilen_mit_bezug: null,
    bezugswerte: ids[name].size,
    verschieden: ids[name].size,
    passend: ids[name].size,
    fehlend: 0,
    hinweis: `${pfad} vollstaendig gelesen`,
  }});
}

function gueltig(v) {
  return v !== null && v !== undefined && v !== false && v !== '';
}

function pruefe(name, quelle, extraktor, ziel, hinweis) {
  const zielSet = ziel ? ids[ziel] : null;
  let mit = 0;
  let ohne = 0;
  let mehrfach = 0;
  let werte = 0;
  let passend = 0;
  let fehlend = 0;
  const verschieden = new Set();

  for (const row of daten[quelle]) {
    let roh = extraktor(row);
    if (!Array.isArray(roh)) roh = [roh];
    const vals = roh.filter(gueltig).map(String);
    if (vals.length === 0) ohne += 1;
    else mit += 1;
    if (vals.length > 1) mehrfach += 1;
    for (const v of vals) {
      werte += 1;
      verschieden.add(v);
      if (zielSet) {
        if (zielSet.has(v)) passend += 1;
        else fehlend += 1;
      }
    }
  }

  ausgabe.push({ json: {
    schritt: 'S52',
    bereich: 'B Beziehung',
    beziehung: name,
    quellzeilen: daten[quelle].length,
    zeilen_mit_bezug: mit,
    bezugswerte: werte,
    verschieden: verschieden.size,
    passend: zielSet ? passend : null,
    fehlend: zielSet ? fehlend : null,
    hinweis: `${hinweis} / ohne Bezug ${ohne} / Mehrfachbezug ${mehrfach}`,
  }});
}

pruefe('vat.country → countries.id', 'vat', r => r.country, 'countries', 'Umsatzsteuerland');
pruefe('categories.category → categories.id', 'categories', r => r.category, 'categories', 'Hierarchische Oberkategorie');
pruefe('offers.category → categories.id', 'offers', r => r.category, 'categories', 'Angebotskategorie');
pruefe('offers.country → countries.id', 'offers', r => r.country, 'countries', 'Angebotsland');
pruefe('offers.vat → vat.id', 'offers', r => r.vat, 'vat', 'Umsatzsteuerregel');
pruefe('users.country → countries.id', 'users', r => r.country, 'countries', 'Teilnehmerland');
pruefe('dates.offer → offers.id', 'dates', r => r.offer, 'offers', 'Terminangebot');
pruefe('dates.leader[] → admins.id', 'dates', r => r.leader ?? [], 'admins', 'Trainerzuordnung');
pruefe('bookings.offer → offers.id', 'bookings', r => r.offer, 'offers', 'Buchungsangebot');
pruefe('bookings.users[].user → users.id', 'bookings', r => (r.users ?? []).map(x => x?.user), 'users', 'Buchungsteilnehmer');
pruefe('bookings.users[].pricecategory → pricecategories.id', 'bookings', r => (r.users ?? []).map(x => x?.pricecategory), 'pricecategories', 'Gebuchte Preiskategorie');
pruefe('pricecategories.offer → offers.id', 'pricecategories', r => r.offer, 'offers', 'Preiskategorie des Angebots');
pruefe('attendances.date → dates.id', 'attendances', r => r.date, 'dates', 'Anwesenheit am Termin');
pruefe('attendances.user → users.id', 'attendances', r => r.user, 'users', 'Anwesenheitsbenutzer');
pruefe('attendances.participant', 'attendances', r => r.participant, null, 'Keine Teilnehmertabelle im vorgegebenen Zwölfermodell');
pruefe('invoices.user → users.id', 'invoices', r => r.user, 'users', 'Rechnungsempfaenger');
pruefe('invoices.paytrans → transactions.id', 'invoices', r => r.paytrans, 'transactions', 'Zahlungstransaktion');
pruefe('transactions.booking → bookings.id', 'transactions', r => r.booking, 'bookings', 'Transaktionsbuchung');
pruefe('transactions.offer → offers.id', 'transactions', r => r.offer, 'offers', 'Transaktionsangebot');
pruefe('transactions.user → users.id', 'transactions', r => r.user, 'users', 'Transaktionsbenutzer');
pruefe('transactions.userdata.id → users.id', 'transactions', r => r.userdata?.id, 'users', 'Eingebettete Benutzerkennung');
pruefe('transactions.pay', 'transactions', r => r.pay, null, 'Zielressource pay ist nicht Teil des vorgegebenen Zwölfermodells');

return ausgabe;
